package com.rpb.reservation.workforce.statutory.settlement;

import static com.rpb.reservation.workforce.statutory.settlement.SettlementDtos.*;
import static com.rpb.reservation.workforce.payroll.supplemental.SupplementalMoney.*;
import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.workforce.payroll.*;
import com.rpb.reservation.workforce.payroll.supplemental.*;
import com.rpb.reservation.workforce.statutory.annual.*;
import com.rpb.reservation.workforce.persistence.WorkforceDirectory;
import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;import java.math.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

@Service @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class SettlementService {
 private final WorkforceAccess gate;private final PayrollAccess access;private final WorkforceDirectory directory;private final SettlementRepository repository;private final SupplementalRepository commands;private final JdbcTemplate jdbc;private final WorkforceJson json;private final WorkforceAudit audit;private final Clock clock;
 public SettlementService(WorkforceAccess gate,PayrollAccess access,WorkforceDirectory directory,SettlementRepository repository,SupplementalRepository commands,JdbcTemplate jdbc,WorkforceJson json,WorkforceAudit audit,Clock clock){this.gate=gate;this.access=access;this.directory=directory;this.repository=repository;this.commands=commands;this.jdbc=jdbc;this.json=json;this.audit=audit;this.clock=clock;}
 private void enter(CurrentActor a,UUID store,UUID company,UUID employee){access.enter(a,store,company);if(employee!=null)access.employee(a,company,employee);}
 private void headquarters(CurrentActor a){gate.headOffice(a);for(var s:directory.stores(a.tenantId()))gate.enter(a,s.id());}
 private void lock(CurrentActor a,UUID command){new PayrollRepository(jdbc,json).lockSources(a.tenantId());commands.commandLock(command);}
 private SettlementProjection projection(){return new SettlementProjection(jdbc,json,clock);}
 private CompanySdlProjection companyProjection(){return new CompanySdlProjection(jdbc,json,clock);}
 public EvidencePage read(CurrentActor a,UUID store,UUID company,UUID employee,String period){enter(a,store,company,employee);var month=PayrollProfileValidation.month(period);var saved=repository.evidence(a.tenantId(),company,employee,month);var balance=projection().read(a.tenantId(),company,employee,month);var annual=new AnnualWageRepository(jdbc,json,clock).capture(a.tenantId(),company,employee,month.getYear());return new EvidencePage(company,employee,period,saved.version(),saved.evidence(),balance,gate.isHeadOffice(a),commands.hash(Arrays.asList(annual,saved,balance,companyProjection().read(a.tenantId(),company,month,null,BigDecimal.ZERO))));}
 @Transactional public EvidencePage save(CurrentActor a,UUID store,UUID company,UUID employee,String period,Evidence c){enter(a,store,company,employee);headquarters(a);validate(c);var month=PayrollProfileValidation.month(period);lock(a,c.commandId());var replay=commands.replay(a,store,employee,c.commandId(),"evidence:"+company+":"+period,c,EvidencePage.class);if(replay.isPresent())return replay.get();var old=repository.evidence(a.tenantId(),company,employee,month);if(old.version()!=c.expectedVersion())throw WorkforceException.conflict();repository.evidence(a.tenantId(),company,employee,month,c,a.actorId());var result=read(a,store,company,employee,period);commands.command(a,store,company,employee,c.commandId(),"evidence:"+company+":"+period,c,result);audit.changed(a,store,"statutory.evidence",employee,old,result);return result;}
 private void validate(Evidence c){if(c==null||c.commandId()==null||c.expectedVersion()==null||c.expectedVersion()<0||c.evidenceReference()==null||c.evidenceReference().isBlank()||c.evidenceReference().length()>1000)throw WorkforceException.invalid();for(var s:Arrays.asList(c.employeeCpfDeducted(),c.cdacDeducted(),c.recognisedSdl(),c.recognisedCdac(),c.manualCdac()))nonnegative(s);if(c.remitted()!=null)for(var s:Arrays.asList(c.remitted().employeeCpf(),c.remitted().employerCpf(),c.remitted().sdl(),c.remitted().cdac()))nonnegative(s);if(c.discoveryDate()!=null&&c.discoveryDate().isAfter(today()))throw WorkforceException.invalid();if(c.recovery()!=null){var r=c.recovery();if(!Set.of("ordinary_employer_omission","ordinary_non_negligent_recovery","aw_statutory_reassessment","already_deducted_unremitted","unclassified").contains(Objects.toString(r.cause(),"")))throw WorkforceException.invalid();nonnegative(r.maximum());}if(c.interest()!=null){var i=c.interest();if(!Set.of("unknown","assessed","not_applicable").contains(Objects.toString(i.state(),""))||!i.state().equals("unknown")&&(i.officialReference()==null||i.officialReference().isBlank())||i.state().equals("assessed")&&i.assessedAmount()==null||i.state().equals("unknown")&&i.assessedAmount()!=null)throw WorkforceException.invalid();nonnegative(i.assessedAmount());}}
 private void nonnegative(String s){if(s!=null&&(number(s).signum()<0||number(s).scale()>2))throw WorkforceException.invalid();}
 private LocalDate today(){return LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore")));}
 public CompanySdl company(CurrentActor a,UUID store,UUID company,String period){enter(a,store,company,null);var result=companyProjection().read(a.tenantId(),company,PayrollProfileValidation.month(period),null,BigDecimal.ZERO);return new CompanySdl(result.companyId(),result.month(),result.version(),result.evidence(),result.target(),result.recognised(),result.remitted(),result.liabilityDelta(),result.remittanceBalance(),result.individualTotal(),result.roundingAdjustment(),result.issues(),gate.isHeadOffice(a));}
 @Transactional public CompanySdl company(CurrentActor a,UUID store,UUID company,String period,CompanyEvidence c){enter(a,store,company,null);headquarters(a);if(c==null||c.commandId()==null||c.expectedVersion()==null||c.expectedVersion()<0||c.evidenceReference()==null||c.evidenceReference().isBlank()||c.evidenceReference().length()>1000||c.employeeIds()==null||c.employeeIds().isEmpty()||new HashSet<>(c.employeeIds()).size()!=c.employeeIds().size())throw WorkforceException.invalid();for(var id:c.employeeIds())access.employee(a,company,id);nonnegative(c.recognisedSdl());nonnegative(c.remittedSdl());var month=PayrollProfileValidation.month(period);lock(a,c.commandId());var replay=commands.replay(a,store,company,c.commandId(),"company-evidence:"+period,c,CompanySdl.class);if(replay.isPresent())return replay.get();var old=companyProjection().saved(a.tenantId(),company,month);if(old.version()!=c.expectedVersion())throw WorkforceException.conflict();companyProjection().save(a.tenantId(),company,month,c,a.actorId());var result=company(a,store,company,period);commands.command(a,store,company,company,c.commandId(),"company-evidence:"+period,c,result);audit.changed(a,store,"statutory.company-evidence",company,old,result);return result;}
 public List<Remittance> remittances(CurrentActor a,UUID store,UUID company){enter(a,store,company,null);return repository.remittances(a.tenantId(),company);}
 public Remittance remittance(CurrentActor a,UUID store,UUID id){gate.enter(a,store);var r=repository.remittance(a.tenantId(),id).orElseThrow(WorkforceException::missing);enter(a,store,r.companyId(),null);return r;}
 @Transactional public Remittance remit(CurrentActor a,UUID store,UUID id,RemittanceWrite c){
  if(c==null||id==null||c.commandId()==null||c.companyId()==null||c.paymentDate()==null||c.paymentDate().isAfter(today())||c.reference()==null||c.reference().isBlank()||c.reference().length()>1000||c.note()==null||c.note().isBlank()||c.note().length()>1000||c.allocations()==null||c.allocations().isEmpty()||c.allocations().size()>100)throw WorkforceException.invalid();enter(a,store,c.companyId(),null);lock(a,c.commandId());var replay=commands.replay(a,store,id,c.commandId(),"remit",c,Remittance.class);if(replay.isPresent())return replay.get();if(repository.remittance(a.tenantId(),id).isPresent())throw WorkforceException.conflict();var keys=new HashSet<String>();
  for(var v:c.allocations()){if(v==null||!Set.of("cpf_employee","cpf_employer","sdl","cdac","interest").contains(Objects.toString(v.component(),""))||v.component().equals("sdl")!=(v.employeeId()==null)||v.amount()==null||number(v.amount()).signum()<=0||number(v.amount()).scale()>2||!keys.add(v.employeeId()+":"+v.month()+":"+v.component()))throw WorkforceException.invalid();var month=PayrollProfileValidation.month(v.month());if(c.paymentDate().isBefore(month.atDay(1)))throw WorkforceException.invalid();if(v.employeeId()!=null)access.employee(a,c.companyId(),v.employeeId());if(c.reversesId()==null){String outstanding;if(v.component().equals("sdl"))outstanding=companyProjection().read(a.tenantId(),c.companyId(),month,null,BigDecimal.ZERO).remittanceBalance();else{var balance=projection().read(a.tenantId(),c.companyId(),v.employeeId(),month);outstanding=switch(v.component()){case "cpf_employee"->balance.employeeCpf().remittanceBalance();case "cpf_employer"->balance.employerCpf().remittanceBalance();case "cdac"->balance.cdac().remittanceBalance();case "interest"->balance.interest().state().equals("assessed")?difference(balance.interest().assessedAmount(),money(repository.remitted(a.tenantId(),c.companyId(),v.employeeId(),month,"interest"))):null;default->null;};}if(outstanding==null)throw new WorkforceException("STATUTORY_REMITTANCE_UNKNOWN",409);if(number(v.amount()).compareTo(number(outstanding))>0)throw new WorkforceException("STATUTORY_REMITTANCE_EXCEEDS_BALANCE",409);}}
  if(c.reversesId()!=null){var original=remittance(a,store,c.reversesId());if(!original.companyId().equals(c.companyId())||original.reversesId()!=null||!original.allocations().equals(c.allocations())||c.paymentDate().isBefore(original.paymentDate())||repository.remittances(a.tenantId(),c.companyId()).stream().anyMatch(r->original.id().equals(r.reversesId())))throw WorkforceException.conflict();}
  var result=new Remittance(id,c.companyId(),c.paymentDate(),c.reference(),List.copyOf(c.allocations()),c.reversesId(),c.note(),a.actorId(),clock.instant());repository.remittance(a.tenantId(),result);commands.command(a,store,c.companyId(),id,c.commandId(),"remit",c,result);audit.changed(a,store,"statutory.remittance",id,null,result);return result;
 }
 public List<ReconciliationPage> reconciliations(CurrentActor a,UUID store,UUID company,UUID employee,int year){enter(a,store,company,employee);return new AnnualWageRepository(jdbc,json,clock).reconciliations(a.tenantId(),company,employee,year).stream().map(r->reconciliation(a,store,r.id())).toList();}
 public ReconciliationPage reconciliation(CurrentActor a,UUID store,UUID id){gate.enter(a,store);var r=repository.reconciliation(a.tenantId(),id).orElseThrow(WorkforceException::missing);enter(a,store,r.companyId(),r.employeeId());var context=new AnnualWageRepository(jdbc,json,clock).capture(a.tenantId(),r.companyId(),r.employeeId(),r.year());var target=new AnnualWageCalculator().assess(context);return new ReconciliationPage(r,context.months().stream().filter(f->Set.of("actual","known-zero").contains(f.state())).map(f->projection().read(a.tenantId(),r.companyId(),r.employeeId(),context,target,YearMonth.parse(f.month()))).toList(),repository.settled(a.tenantId(),id));}
 @Transactional public Settlement settle(CurrentActor a,UUID store,UUID id,SettleWrite c){
  var first=reconciliation(a,store,id);headquarters(a);validate(c);lock(a,c.commandId());var replay=commands.replay(a,store,id,c.commandId(),"reconcile-settle",c,Settlement.class);if(replay.isPresent())return replay.get();var page=reconciliation(a,store,id);var r=page.reconciliation();if(page.settled())throw WorkforceException.conflict();var context=new AnnualWageRepository(jdbc,json,clock).capture(a.tenantId(),r.companyId(),r.employeeId(),r.year());if(!r.assessment().fingerprint().equals(c.expectedFingerprint())||!context.fingerprint().equals(c.expectedFingerprint()))throw new WorkforceException("AW_CONTEXT_STALE",409);if(!r.assessment().status().equals("ready"))throw new WorkforceException("STATUTORY_SETTLEMENT_BLOCKED",409);
  var settlement=new Settlement(c.commandId(),r.companyId(),r.employeeId(),r.settlementMonth(),r.id(),page.balances(),clock.instant(),context);for(var m:page.balances()){writeCpf(a.tenantId(),r.companyId(),r.employeeId(),m,YearMonth.parse(r.settlementMonth()),r.id(),"assessment:"+r.id());}repository.settlement(a.tenantId(),settlement);commands.command(a,store,r.companyId(),id,c.commandId(),"reconcile-settle",c,settlement);audit.changed(a,store,"statutory.reconcile-settle",id,first,settlement);return settlement;
 }
 @Transactional public Settlement settleMonth(CurrentActor a,UUID store,UUID company,UUID employee,String period,SettleWrite c){enter(a,store,company,employee);headquarters(a);validate(c);lock(a,c.commandId());var replay=commands.replay(a,store,employee,c.commandId(),"month-settle:"+company+":"+period,c,Settlement.class);if(replay.isPresent())return replay.get();var page=read(a,store,company,employee,period);if(!page.fingerprint().equals(c.expectedFingerprint()))throw new WorkforceException("SUPPLEMENTAL_SOURCE_CHANGED",409);var month=PayrollProfileValidation.month(period);var settlement=YearMonth.from(today());var context=new AnnualWageRepository(jdbc,json,clock).capture(a.tenantId(),company,employee,month.getYear());writeCpf(a.tenantId(),company,employee,page.balance(),settlement,null,"month:"+c.commandId());var result=new Settlement(c.commandId(),company,employee,settlement.toString(),null,List.of(page.balance()),clock.instant(),context);repository.settlement(a.tenantId(),result);commands.command(a,store,company,employee,c.commandId(),"month-settle:"+company+":"+period,c,result);audit.changed(a,store,"statutory.month-settle",employee,null,result);return result;}
 private void validate(SettleWrite c){if(c==null||c.commandId()==null||c.expectedFingerprint()==null||c.note()==null||c.note().isBlank()||c.note().length()>1000)throw WorkforceException.invalid();}
 private void writeCpf(UUID tenant,UUID company,UUID employee,MonthBalance m,YearMonth settlement,UUID assessment,String key){if(m.employeeCpf().liabilityDelta()==null||m.employerCpf().liabilityDelta()==null)throw new WorkforceException("STATUTORY_SETTLEMENT_BLOCKED",409);repository.liability(tenant,company,employee,YearMonth.parse(m.month()),settlement,"cpf_employee",m.employeeCpf().liabilityDelta(),null,assessment,key,m);repository.liability(tenant,company,employee,YearMonth.parse(m.month()),settlement,"cpf_employer",m.employerCpf().liabilityDelta(),null,assessment,key,m);}
}
